"""Seven named Core formulae, reviewed visually at PDF 284–289.

Method rules are included in every formula. This does not model learning a
second method or each imitated-power recipe as one generic reusable formula.
"""
import json,sys
from pathlib import Path
repo=Path(__file__).resolve().parent.parent;work=Path(sys.argv[1])
source=next(s for s in json.loads((work/'pages/manifest.json').read_text(encoding='utf-8')) if s['id']=='core-v5')
common_pt=[
('Destilação e aprendizado','Cada fórmula exige o próprio Vitae, equivalente a um Teste de Sangue para destilar, e sangue humano da Ressonância indicada. O custo de ativação é separado. Ao ativar, a rolagem de destilação mede a qualidade; testes próprios do poder também são feitos quando necessários, substituindo a Disciplina imitada por Alquimia. Recebe uma fórmula gratuita por ponto em Alquimia; outras custam nível × 3 XP e pesquisa. Registre separadamente receitas e ingredientes.'),
('Qualidade da mistura','| Sucessos | Resultado |\n| --- | --- |\n| 2 | Efeito fraco, imprevisto ou atrasado |\n| 4 | Funciona como pretendido |\n| 6 | Efeito ampliado |'),
('Ingredientes e ajustes','Ingredientes listados são sugestões: receitas autorais podem variar, mas o próprio Vitae é indispensável e quase sempre há sangue humano com Ressonância específica. Sangue frio ou coagulado pode servir em quantidade suficiente. Ingredientes podem incluir emoções ou experiências. O Narrador ajusta a parada em um ou dois dados conforme qualidade e originalidade. Referências: +1 por ingrediente raro ou caro (exige história ou Recursos acima do nível da fórmula); −1 por substituto barato, sem penalizar ingredientes comuns já previstos na receita; +1 por ingrediente mágico ou muito potente (Discrasia, sangue de lobisomem ou Vitae com Potência dois níveis acima da fórmula); −1 por sangue hospitalar ou adereços esotéricos banais; +1 por criatividade que gere complicações ou avance a história.'),
('Escolha do método','Escolha um método ao adquirir o primeiro ponto de Alquimia. Outro método começa do zero e conta como Disciplina separada. Fórmulas aprendidas num método não passam automaticamente a outro: cada receita precisa ser aprendida por método.'),
('Athanor Corporis','Usa o próprio corpo como forno. Beba os sangues ressonantes e destile internamente com Vigor + Alquimia e um Teste de Sangue. Só um poder pode estar ativo de cada vez. É preciso destilar um novo antes de ativá-lo, normalmente gastando ao menos três turnos de concentração sem fazer outra coisa.'),
('Calcinatio','Usa um humano como forno, ajustando seu estado biofísico com pressão emocional, encantos ou drogas e alimentando-o com Vitae. Pague a destilação e use Manipulação + Alquimia. Para ativar, beba sangue que sacie Fome igual ao nível da fórmula menos 1. Só uma fórmula por vítima; ela permanece enquanto o humano conservar o estado emocional. Ativar demora o tempo de drenar a quantidade de sangue necessária.'),
('Fixatio','Usa forno ou aparelho alquímico e ingredientes inertes. Pague a destilação; a parada é Inteligência + Alquimia, rolada ao consumir, não ao produzir. Sem laboratório, improviso só permite fórmulas até nível 3, com −2 dados por equipamento inadequado. Pode carregar fórmulas de qualquer nível em quantidade igual a Raciocínio ou Destreza; pode armazenar até 2 × (Alquimia + Refúgio), com conservação adequada. Tamanho dos recipientes depende do Narrador. Pode ativar um poder por turno.')]
common_en=[
('Distillation and learning','Every formula requires the alchemist’s Vitae equivalent to one Rouse Check to distill, and human blood of the indicated Resonance. Activation cost is separate. On activation, the distillation roll measures quality; the power’s own rolls are also made as required, replacing an imitated Discipline with Alchemy. Gain one free formula per Alchemy dot; additional formulae cost level × 3 XP and research. Record recipes and ingredients separately.'),
('Mixture quality','| Successes | Result |\n| --- | --- |\n| 2 | Weak, unexpected or delayed effect |\n| 4 | Works as intended |\n| 6 | Enhanced effect |'),
('Ingredients and adjustments','Listed ingredients are suggestions: personal recipes may vary, but the alchemist’s Vitae is essential and specific human Resonance is almost always needed. Cold or clotted blood may work in sufficient quantity. Ingredients may include emotions or experiences. The Storyteller adjusts pools by one or two dice for quality and originality. Guidelines: +1 per rare or expensive ingredient (requires a story or Resources above the formula level); −1 per cheap substitute, without penalizing common ingredients already specified; +1 per magical or powerful ingredient (Dyscrasia, werewolf blood or Vitae with Potency two levels above the formula); −1 for hospital blood or mundane occult trinkets; +1 for creativity that creates complications or advances the story.'),
('Choosing a method','Choose one method with the first Alchemy dot. Another method starts from zero and counts as a separate Discipline. Formulae learned in one method do not transfer automatically: each recipe must be learned for each method.'),
('Athanor Corporis','Uses the alchemist’s body as furnace. Drink the resonant bloods and distill internally with Stamina + Alchemy and one Rouse Check. Only one power can be active at a time. A new power must be distilled before activation, normally requiring at least three turns of concentration with no other actions.'),
('Calcinatio','Uses a human as furnace, adjusting their biophysical state with emotional pressure, incantations or drugs and feeding them Vitae. Pay distillation cost and roll Manipulation + Alchemy. To activate, drink blood slaking Hunger equal to formula level minus 1. Only one formula per victim; it persists while the human retains the emotional state. Activation takes the time needed to drain that much blood.'),
('Fixatio','Uses a furnace or alchemical apparatus with inert ingredients. Pay distillation cost; the pool is Intelligence + Alchemy, rolled when consuming rather than producing. Without a lab, improvised equipment permits only formulae up to level 3, with −2 dice for inadequate equipment. Carry formulae of any level up to Wits or Dexterity; store up to 2 × (Alchemy + Haven) with appropriate preservation. Container size depends on the Storyteller. May activate one power per turn.')]
rows=[
('far-reach','Longo Alcance','Far Reach',1,[286,287],[
('Descrição','Move objetos ou pessoas pela mente, sem contato.'),('Ingredientes','Vitae do alquimista, sangue humano colérico e fibras de nylon derretidas, ímã de geladeira ralado ou nootrópicos incomuns.'),('Custo de ativação','Um Teste de Sangue.'),('Parada','Determinação + Alquimia contra Força + Atletismo de alvo resistente. Manipulação sutil usa Raciocínio + Alquimia, Dificuldade pelo Narrador.'),('Sistema','Levante, empurre ou puxe objeto ou pessoa com menos de 100 kg, à vista e a menos de dez metros. Objetos podem quebrar se frágeis, mas normalmente não se movem rápido o suficiente para ferir por impacto. Exceção: faca ou ferramenta metálica pequena pode ser empunhada com Determinação + Alquimia, −2 dados pela precisão; faca só causa +1 dano. Contra pessoa resistente, vitória permite puxar para alcance de agarrar ou garras, ou arremessar um metro por ponto de margem, causando a margem em dano superficial e deixando-a caída. Manter algo no ar exige Determinação + Alquimia, Dificuldade 3, a cada turno.'),('Duração','Um turno, salvo manutenção por testes.')],[
('Description','Moves objects or people mentally without contact.'),('Ingredients','The alchemist’s Vitae, choleric human blood, and melted nylon fibers, grated refrigerator magnet or unusual nootropics.'),('Activation cost','One Rouse Check.'),('Dice Pool','Resolve + Alchemy opposed by a resisting target’s Strength + Athletics. Subtle manipulation uses Wits + Alchemy at a Storyteller-set Difficulty.'),('System','Lift, push or pull an object or person under 100 kg, in sight and less than ten meters away. Fragile objects may break, but normally do not move fast enough to injure by impact. Exception: a knife or small metal tool can be wielded with Resolve + Alchemy at −2 dice for precision; a knife provides only +1 damage. Against a resisting person, a win pulls them into grapple or claw range, or throws them one meter per margin, inflicting the margin as Superficial damage and leaving them prone. Holding something aloft requires Resolve + Alchemy, Difficulty 3, each turn.'),('Duration','One turn unless maintained with rolls.')]),
('haze','Neblina','Haze',1,[287],[
('Descrição','Cria névoa que acompanha o alquimista, disfarçando rosto e silhueta.'),('Ingredientes','Vitae do alquimista, sangue humano fleumático e gelo seco ou fumaça de charuto ou escapamento.'),('Custo de ativação','Um Teste de Sangue; pode fazer outro para estender a nuvem a um grupo de até cinco pessoas.'),('Sistema','Quem tenta identificar ou acertar o usuário com ataque à distância recebe −2 dados.'),('Duração','Uma cena ou até encerrar voluntariamente.')],[
('Description','Creates mist following the alchemist, disguising face and silhouette.'),('Ingredients','The alchemist’s Vitae, phlegmatic human blood and dry ice, cigar smoke or exhaust smoke.'),('Activation cost','One Rouse Check; another can extend the cloud to a group of up to five people.'),('System','Anyone trying to identify or hit the user with a ranged attack takes −2 dice.'),('Duration','One scene or until voluntarily ended.')]),
('envelop','Envolver','Envelop',2,[287],[
('Descrição','Névoa envolve um alvo à vista, cegando-o parcialmente e podendo sufocar mortal.'),('Ingredientes','Vitae do alquimista, sangue humano melancólico ou fleumático, cloreto de potássio, poluição ou gás halon.'),('Custo de ativação','Um Teste de Sangue.'),('Parada','Raciocínio + Alquimia contra Vigor + Sobrevivência para sufocar mortal.'),('Sistema','O alvo recebe −3 dados para detecção visual e ataques à distância. Contra mortal, vencer o conflito de sufocamento impede qualquer ação além de tossir e sufocar; crítico o deixa inconsciente. Só pode manter um alvo individual por vez.'),('Duração','Até o fim da cena ou encerrar voluntariamente.')],[
('Description','Mist surrounds a target in sight, impairing vision and potentially suffocating a mortal.'),('Ingredients','The alchemist’s Vitae, melancholic or phlegmatic human blood, potassium chloride, pollution or halon gas.'),('Activation cost','One Rouse Check.'),('Dice Pool','Wits + Alchemy opposed by Stamina + Survival to suffocate a mortal.'),('System','The target takes −3 dice to visual detection and ranged attacks. Against a mortal, winning the suffocation contest prevents actions other than coughing and choking; a critical renders them unconscious. Only one individual target at a time.'),('Duration','Until scene’s end or voluntarily ended.')]),
('defractionate','Defracionar','Defractionate',3,[287],[
('Descrição','Elixir restaura sangue hospitalar fracionado, tornando-o nutritivo mesmo sem Esôfago de Ferro.'),('Ingredientes','Vitae do alquimista, sangue humano melancólico ou sanguíneo, poucos mililitros de sangue O negativo, espinafre mofado, café quente e octanoato de sódio.'),('Custo de ativação','A fonte não indica Teste de Sangue adicional para ativar; a destilação tem o custo geral.'),('Sistema','Em Athanor Corporis ou Calcinatio, extraia da própria veia ou da bolsa humana; em Fixatio, use o preparado. Cada sucesso de destilação transforma uma bolsa que sacia 1 Fome em sangue integral. Qualquer vampiro pode bebê-lo para saciar Fome. Athanor: extraia uma vez por noite sem pagar nova destilação até a próxima alimentação ou Fome 5. Calcinatio: se sobreviver, a bolsa permite nova extração após uma semana sem nova destilação, sofrendo 3 danos agravados em Vitalidade a cada extração.'),('Duração','A fonte não especifica prazo de validade do sangue restaurado; os limites de extração estão acima.')],[
('Description','An elixir restores fractionated hospital blood, making it nourishing without Iron Gullet.'),('Ingredients','The alchemist’s Vitae, melancholic or sanguine human blood, a few milliliters of O-negative blood, moldy spinach, hot coffee and sodium octanoate.'),('Activation cost','The source lists no additional activation Rouse Check; distillation has its general cost.'),('System','With Athanor Corporis or Calcinatio, extract from your vein or human vessel; with Fixatio, use the preparation. Each distillation success restores one bag slaking 1 Hunger to whole blood. Any vampire may drink it to slake Hunger. Athanor: extract once per night without a new distillation cost until the next feeding or Hunger 5. Calcinatio: a surviving vessel permits another extraction after one week without new distillation, suffering 3 Aggravated Health damage each time.'),('Duration','The source gives no expiry for restored blood; extraction limits are stated above.')],['Defracionado']),
('profane-hieros-gamos','Hieros Gamos Profano','Profane Hieros Gamos',3,[287,288],[
('Descrição','Após purificação e meditação, adapta a morfologia humana exterior à forma idealizada ou profundamente desejada, inclusive de mortais ou outros vampiros.'),('Ingredientes','Vitae do alquimista, sangue humano melancólico ou fleumático e substâncias enteogênicas.'),('Custo de ativação','Um Teste de Sangue para vampiro; 1 dano agravado em Vitalidade para mortal, ao misturar à fórmula sangue do próprio bebedor.'),('Parada','O bebedor testa Vigor + Determinação, Dificuldade 8 menos os sucessos de destilação; vampiro soma sua Severidade da Fraqueza à Dificuldade.'),('Sistema','O bebedor entra em sonho febril e catatônico até a noite seguinte. Vitória transforma o corpo na forma desejada, dentro do espectro humano; não permite formas fantásticas. Crítico pode conceder ou remover Qualidades e Defeitos de Aparência, pagando XP como outras Vantagens. Crítico bestial ou falha bestial pode manifestar novo Defeito, como Repulsivo, Predador Manifesto, Estigma ou Organívoro. Não remove a Fraqueza Nosferatu: a nova forma incorpora sua aflição.'),('Duração','Permanente até repetir o processo.')],[
('Description','After purification and meditation, reshapes external human morphology toward an idealized or deeply desired form, including for mortals or other vampires.'),('Ingredients','The alchemist’s Vitae, melancholic or phlegmatic human blood and entheogenic substances.'),('Activation cost','One Rouse Check for a vampire; 1 Aggravated Health damage for a mortal, mixing the drinker’s own blood with the formula.'),('Dice Pool','The drinker rolls Stamina + Resolve, Difficulty 8 minus distillation successes; a vampire adds Bane Severity to Difficulty.'),('System','The drinker enters a feverish catatonic dream until the following night. A win reshapes the body within the human anatomical spectrum, not into fantastic forms. A critical may grant or remove Looks Merits and Flaws, paying XP as with other Advantages. A messy critical or bestial failure may manifest a new Flaw such as Repulsive, Obvious Predator, Stigmata or Organovore. It does not remove the Nosferatu Bane: the new form incorporates their affliction.'),('Duration','Permanent until the process is repeated.')]),
('airborne-momentum','Ímpeto Aéreo','Airborne Momentum',4,[289],[
('Descrição','Permite ao alquimista voar ou pairar em qualquer direção, inclusive verticalmente.'),('Ingredientes','Vitae do alquimista, sangue humano colérico e sanguíneo, champagne, sangue de pássaro, hélio, extrato de escopolamina ou beladona.'),('Custo de ativação','Um Teste de Sangue.'),('Parada','Força + Alquimia contra Força + Atletismo para carregar alvo resistente ou para oponente tentar puxar o voador ao chão.'),('Sistema','Só o alquimista voa, aproximadamente à velocidade de corrida. Pode carregar massa de um humano médio, reduzindo a velocidade para caminhada.'),('Duração','Uma cena.')],[
('Description','Allows the alchemist to fly or hover in any direction, including vertically.'),('Ingredients','The alchemist’s Vitae, choleric and sanguine human blood, champagne, bird blood, helium, scopolamine extract or belladonna.'),('Activation cost','One Rouse Check.'),('Dice Pool','Strength + Alchemy opposed by Strength + Athletics to carry an unwilling target or when an opponent pulls the flyer down.'),('System','Only the alchemist flies, approximately at running speed. Carrying an average human’s mass reduces speed to walking.'),('Duration','One scene.')]),
('awaken-sleeper','Despertar Adormecido','Awaken the Sleeper',5,[289],[
('Descrição','Elixir adicionado a sangue humano desperta um vampiro em Torpor.'),('Ingredientes','Vitae do alquimista, sangue humano colérico ou sanguíneo, adrenalina, carbonato de amônio, água amoniacal, cafeína ou benzedrina, melatonina.'),('Custo de ativação','A fonte não indica Teste de Sangue adicional para ativar; a destilação tem o custo geral.'),('Sistema','Extraia da bolsa em Calcinatio ou da própria veia em Athanor, salvo em Fixatio, e misture a sangue humano. Sucessos de destilação menos 2 determinam a Potência de Sangue máxima que pode despertar: 5 sucessos despertam Potência 3 ou menor. Athanor: extração uma vez por noite sem nova destilação até se alimentar ou Fome 5. Calcinatio: se a bolsa sobreviver, extraia novamente após uma semana sem nova destilação; cada extração causa 5 danos agravados em Vitalidade à bolsa. Também pode alimentar o adormecido diretamente com sangue da bolsa.'),('Duração','Desperta o alvo do Torpor; a fonte não fixa validade do elixir.')],[
('Description','An elixir added to human blood awakens a vampire from torpor.'),('Ingredients','The alchemist’s Vitae, choleric or sanguine human blood, adrenaline, ammonium carbonate, ammonia solution, caffeine or benzedrine, and melatonin.'),('Activation cost','The source lists no additional activation Rouse Check; distillation has its general cost.'),('System','Extract from the Calcinatio vessel or your Athanor vein unless using Fixatio, then mix with human blood. Distillation successes minus 2 determine the maximum Blood Potency awakened: 5 successes awaken Potency 3 or lower. Athanor: extract once per night without new distillation until feeding or Hunger 5. Calcinatio: a surviving vessel allows extraction again after one week without new distillation; each extraction inflicts 5 Aggravated Health damage on the vessel. May also feed the sleeper directly from the vessel’s blood.'),('Duration','Awakens the target from torpor; the source sets no elixir expiry.')])]

for row in rows:
    slug,pt,en,level,pages,sections_pt,sections_en,*aliases=row
    descriptions={}
    for locale,specific,common in [('pt-BR',sections_pt,common_pt),('en',sections_en,common_en)]:
        values=[{'title':title,'text':text} for title,text in specific]
        values.insert(1,{'title':'Requirements' if locale=='en' else 'Requisitos','text':f'Thin-blood; Thin-Blood Alchemy {level} and the formula learned for the chosen method.' if locale=='en' else f'Sangue-Ralo; Alquimia do Sangue-Fraco {level} e fórmula aprendida para o método escolhido.'})
        values.extend({'title':title,'text':text} for title,text in common)
        descriptions[locale]=values
    id='core-v5-formula-'+slug;refs=sorted(set([284,285,286]+pages))
    entry={'id':id,'kind':'formula','names':{'pt-BR':pt,'en':en},'aliases':[pt,en]+(aliases[0] if aliases else []),'discipline':'Alquimia do Sangue-Fraco','level':level,'versions':[{'id':id+'-core','book':'core-v5','sourceTitle':'Livro Básico V5, pp. '+', '.join(str(p-2) for p in refs),'sourceLanguage':'pt-BR','pdfSha256':source['sha256'],'pages':[{'pdfPage':p,'printedPage':p-2} for p in refs],'requirements':{'disciplines':{'Alquimia do Sangue-Fraco':level},'clans':['Sangue-Ralo']},'descriptions':descriptions}]}
    (repo/'scripts/reviewed-content'/('core-formula-'+slug+'.json')).write_text(json.dumps(entry,ensure_ascii=False,indent=2),encoding='utf-8')
print('Seven named Core formulae reviewed; method-specific learning and imitated recipes still require separate UI modeling')
